    }).pipe(
      // Fresh: the shared test layer has already built the ingestor this replaces.
      Effect.provide(
        Layer.fresh(
          layerFailingWrites([lockTimeout, lockTimeout], (events) =>
            events.some((event) => event.type === "thread.model-selection-updated"),
