describe("orchestration V2 contracts", () => {
  it("round-trips optional model execution metadata through runtime and JSON notices without breaking old histories", () => {
    const notice = {
      id: "model-notice",
      type: "system_notice",
      threadId: "thread-1",
      runId: null,
      nodeId: null,
      providerThreadId: null,
      providerTurnId: null,
      nativeItemRef: null,
      parentItemId: null,
      ordinal: 1,
      status: "completed",
      title: "Model execution",
      startedAt: null,
      completedAt: null,
      updatedAt: now,
      message: "Model phase succeeded",
    };
    const modelExecution = {
      version: 1,
      kind: "phase",
      nativeSessionId: "session",
      phaseId: "primary",
      eventId: "event",
      sourceTimestamp: DateTime.formatIso(now),
      receivedAt: DateTime.formatIso(now),
      status: "succeeded",
      model: "model",
      startSource: "estimated",
      durationMs: 2000,
      gaps: ["Transient start was not observed."],
    };
    const legacy = decodeRuntimeTurnItem(notice);
    expect(legacy.type).toBe("system_notice");
    const runtime = decodeRuntimeTurnItem({ ...notice, modelExecution });
    const wire = encodeWireTurnItem(runtime);
    const json = decodeOrchestrationV2TurnItemJson(wire);
    expect(json.type).toBe("system_notice");
    if (json.type !== "system_notice") throw new Error("Expected system notice.");
    expect(json.modelExecution).toEqual(modelExecution);
    const restored = decodeWireTurnItem(wire);
    expect(restored).toEqual(runtime);
    expect(decodeLegacyNotice(wire)).toEqual({ type: "system_notice", message: notice.message });
    expect(() =>
      decodeRuntimeTurnItem({
        ...notice,
        modelExecution: { ...modelExecution, model: "x".repeat(513) },
      }),
    ).toThrow();
    expect(() =>
      decodeRuntimeTurnItem({
        ...notice,
        modelExecution: { ...modelExecution, gaps: Array.from({ length: 17 }, () => "gap") },
      }),
    ).toThrow();
  });
  it("decodes thread event types from a newer server as skippable items", () => {
    const decodeWireItems = Schema.decodeUnknownSync(
      Schema.toCodecJson(Schema.Array(OrchestrationV2RpcSchemas.subscribeThread.output)),
    );
    const detached = (id: string, sequence: number) => ({
      kind: "event",
      sequence,
      event: {
        id,
        type: "provider-session.detached",
        threadId: "thread-1",
        occurredAt: DateTime.formatIso(now),
        payload: { providerSessionId: "provider-session-1", detachedAt: DateTime.formatIso(now) },
      },
    });

    const items = decodeWireItems([
      detached("event-1", 1),
      {
        kind: "event",
        sequence: 2,
        event: {
          id: "event-2",
          type: "run.from-a-future-server",
          threadId: "thread-1",
          occurredAt: DateTime.formatIso(now),
          payload: { runId: "run-1" },
        },
      },
      detached("event-3", 3),
    ]);

    expect(items.map((item) => item.kind)).toEqual(["event", "unknown-event", "event"]);
    expect(items[1]).toEqual({
      kind: "unknown-event",
      sequence: 2,
      eventType: "run.from-a-future-server",
    });
    expect(() =>
      decodeWireItems([
        { ...detached("event-4", 4), event: { ...detached("event-4", 4).event, payload: {} } },
      ]),
    ).toThrow();
  });

  it("skips turn item types from a newer server in snapshots and turn-item events", () => {
    const decodeWireItems = Schema.decodeUnknownSync(
      Schema.toCodecJson(Schema.Array(OrchestrationV2RpcSchemas.subscribeThread.output)),
    );
    const decodeHistoryPage = Schema.decodeUnknownSync(
      Schema.toCodecJson(OrchestrationV2ThreadHistoryPage),
