              const answer = response.answers?.answer;
              const text =
                typeof answer === "string"
                  ? answer
                  : Array.isArray(answer)
                    ? answer.join(", ")
                    : "";
              if (entry.kind === "input")
                entry.resolve({
                  answer: text,
                  wasFreeform: !(entry.request.choices ?? []).includes(text),
                });
              else
                entry.resolve({
                  approved: text === "Approve",
                  ...(text === "Approve"
                    ? { selectedAction: entry.request.recommendedAction }
                    : {}),
                  ...(text && text !== "Approve" ? { feedback: text } : {}),
                });
            }
          },
          cancel: () => {
            if (entry.kind === "input") entry.resolve({ answer: "", wasFreeform: true });
            else if (entry.kind === "plan") entry.resolve({ approved: false });
          },
        });
        yield* emit({ type: "node.updated", driver: COPILOT_DRIVER, node });
        yield* emit({
          type: "runtime_request.updated",
          driver: COPILOT_DRIVER,
          threadId: open.threadId,
          runtimeRequest: request,
        });
        yield* putItem(turn, id, item);
      });
      yield* Stream.fromQueue(inbox).pipe(
        Stream.runForEach((entry) => {
          if (entry.type === "drain") return Deferred.succeed(entry.receipt, undefined);
          if (entry.type === "accepted") return active?.idle ? terminal(active) : Effect.void;
          return entry.type === "event" ? onEvent(entry.event) : onRequest(entry);
        }),
        Effect.forkScoped,
      );

      const drain = Effect.fnUntraced(function* () {
        const receipt = yield* Deferred.make<void>();
        yield* Queue.offer(inbox, { type: "drain", receipt });
        yield* Deferred.await(receipt).pipe(
          Effect.timeoutOption(15_000),
          Effect.flatMap((result) =>
            Effect.fromOption(result).pipe(
              Effect.mapError(
                () =>
                  new ProviderAdapter.ProviderAdapterProtocolError({
                    driver: COPILOT_DRIVER,
                    detail: "Copilot event drain timed out",
                  }),
              ),
            ),
          ),
        );
      });
      const ensureThread: ProviderAdapter.ProviderAdapterV2SessionRuntime["ensureThread"] =
        Effect.fn("CopilotAdapter.ensureThread")(function* (ensure) {
          if (ensure.forceNewNativeThread)
            return yield* new ProviderAdapter.ProviderAdapterEnsureThreadError({
              driver: COPILOT_DRIVER,
              threadId: ensure.threadId,
              cause: new Error("Native Copilot session replacement is unsupported."),
            });
          if (ensure.modelSelection.instanceId !== input.instanceId)
            return yield* new ProviderAdapter.ProviderAdapterEnsureThreadError({
              driver: COPILOT_DRIVER,
              threadId: ensure.threadId,
              cause: new Error("Copilot model selection targets another account instance."),
            });
          if (providerThread) {
            if (
              ensure.existingProviderThread &&
              ensure.existingProviderThread.id !== providerThread.id
            ) {
              return yield* new ProviderAdapter.ProviderAdapterEnsureThreadError({
                driver: COPILOT_DRIVER,
                threadId: ensure.threadId,
                cause: new Error("Copilot runtime already owns another native thread."),
              });
            }
            return providerThread;
          }
          const previous = ensure.existingProviderThread;
          const nativeId = previous?.nativeThreadRef?.nativeId ?? open.initialNativeThreadId;
          const mcp = yield* mcpSessions.read(open.threadId);
          const autoTier =
            ensure.modelSelection.model === "auto"
              ? yield* sdk("validate routing selection", async () =>
                  autoTierForSelection(
                    ensure.modelSelection,
                    (await client.rpc.models.list({})).auto,
                  ),
                )
              : yield* sdk("validate model selection", async () =>
                  autoTierForSelection(ensure.modelSelection),
                );
          const sessionConfig: SessionConfig = {
            clientName: "t3-code",
            workingDirectory: cwd,
            configDirectory: config.effectiveHome,
            model: ensure.modelSelection.model,
            ...(autoTier ? { capi: { autoTier } } : {}),
            ...(reasoningEffort(ensure.modelSelection)
              ? { reasoningEffort: reasoningEffort(ensure.modelSelection)! }
              : {}),
            streaming: true,
            enableSkills: true,
            enableConfigDiscovery: input.settings.enableConfigDiscovery,
            skipCustomInstructions: !input.settings.enableConfigDiscovery,
            ...(mcp
              ? {
                  systemMessage: {
                    mode: "append",
                    content: t3OrchestrationSystemPrompt(
                      true,
                      mcp.capabilities?.has("device") === true,
                    )!,
                  },
                }
              : {}),
            includeSubAgentStreamingEvents: false,
            ...(mcp
              ? {
                  mcpServers: {
                    "t3-code": {
                      type: "http",
                      url: mcp.endpoint,
                      headers: { Authorization: mcp.authorizationHeader },
                    },
                  },
                }
              : {}),
            // Handle native IDs and applied-decision receipts through the permission RPC.
            onPermissionRequest: (request) => {
              if (!active || active.finished || stopped) {
                sdkOwnedPermissionRequests.add(request);
                return { kind: "user-not-available" };
              }
              return { kind: "no-result" };
            },
            onUserInputRequest: (request) =>
              new Promise((resolve) => {
                if (stopped) resolve({ answer: "", wasFreeform: true });
                else Queue.offerUnsafe(inbox, { type: "request", kind: "input", request, resolve });
              }),
            onExitPlanModeRequest: (request) =>
              new Promise((resolve) => {
                if (stopped) resolve({ approved: false });
                else Queue.offerUnsafe(inbox, { type: "request", kind: "plan", request, resolve });
              }),
            onEvent: (event) => {
              if (event.type === "session.resume" && event.data.alreadyInUse) alreadyInUse = true;
              if (!stopped) Queue.offerUnsafe(inbox, { type: "event", event });
            },
          };
          native = yield* sdk(
            nativeId ? "resume session" : "create session",
            () =>
              nativeId
                ? client.resumeSession(nativeId, { ...sessionConfig, continuePendingWork: false })
                : client.createSession(sessionConfig),
            30_000,
          );
          if (alreadyInUse) {
            yield* sdk("disconnect conflicting session", () => native!.disconnect()).pipe(
              Effect.ignore,
            );
            native = undefined;
            return yield* new ProviderAdapter.ProviderAdapterEnsureThreadError({
              driver: COPILOT_DRIVER,
              threadId: ensure.threadId,
              cause: new Error("Copilot session is already in use by another client."),
            });
          }
          const now = yield* DateTime.now;
          if (nativeId) {
            const transcript = yield* sdk("read native transcript", () => native!.getEvents()).pipe(
              Effect.result,
            );
            if (transcript._tag === "Success") {
              const executionEvents = transcript.success.filter((event) =>
                fusionExecutionKey(event),
              );
              omittedReplayEvents = Math.max(
                0,
                executionEvents.length - MAX_REPLAY_EXECUTION_EVENTS,
              );
              replayExecutionEvents = executionEvents.slice(-MAX_REPLAY_EXECUTION_EVENTS);
              for (const event of transcript.success) {
                if (
                  event.agentId ||
                  (event.type !== "assistant.message" && event.type !== "user.message")
                )
                  continue;
                if (event.type === "assistant.message" && event.data.content.length === 0) continue;
                const messageId = MessageId.make(`${open.providerSessionId}:history:${event.id}`);
                messages.set(messageId, {
                  id: messageId,
                  createdBy: event.type === "user.message" ? "user" : "agent",
                  creationSource: "provider",
                  threadId: ensure.threadId,
                  runId: null,
                  nodeId: null,
                  role: event.type === "user.message" ? "user" : "assistant",
                  text: event.data.content,
                  attachments: [],
                  streaming: false,
                  createdAt: DateTime.makeUnsafe(event.timestamp),
                  updatedAt: DateTime.makeUnsafe(event.timestamp),
                });
              }
            }
          }
          const createdThread: OrchestrationV2ProviderThread = {
            id:
              previous?.id ??
              derive.providerThread({
                driver: COPILOT_DRIVER,
                nativeThreadId: native.sessionId,
                providerInstanceId: input.instanceId,
              }),
            driver: COPILOT_DRIVER,
            providerInstanceId: input.instanceId,
            providerSessionId: open.providerSessionId,
            appThreadId: ensure.threadId,
            ownerNodeId: null,
            nativeThreadRef: ref(native.sessionId),
            nativeConversationHeadRef: null,
            status: "idle",
            firstRunOrdinal: previous?.firstRunOrdinal ?? null,
            lastRunOrdinal: previous?.lastRunOrdinal ?? null,
            handoffIds: previous?.handoffIds ?? [],
            forkedFrom: previous?.forkedFrom ?? null,
            pendingBackgroundTasks: [],
            contextUsage: null,
            nativeMetadata: { modelSelection: ensure.modelSelection },
            goal: null,
            createdAt: previous?.createdAt ?? now,
            updatedAt: now,
          };
          providerThread = createdThread;
          yield* emit({
            type: "provider_thread.updated",
            driver: COPILOT_DRIVER,
            providerThread: createdThread,
          });
          for (const event of replayExecutionEvents) {
            yield* recordFusion(event, true);
            seen.add(event.id);
          }
          replayExecutionEvents = [];
          if (omittedReplayEvents) {
            const timestamp = DateTime.formatIso(yield* DateTime.now);
            yield* putExecution("native-replay-gap", {
              version: 1,
              kind: "gap",
              nativeSessionId: native.sessionId,
              eventId: "native-replay-limit",
              sourceTimestamp: timestamp,
              receivedAt: timestamp,
              status: "incomplete",
              startSource: "unknown",
              gaps: [
                `${omittedReplayEvents} older native execution events were omitted from bounded replay; previously persisted T3 history is retained.`,
              ],
            });
            omittedReplayEvents = 0;
          }
          if (ensure.modelSelection.model === "auto")
            yield* refreshSelection(ensure.modelSelection);
          const skills = yield* sdk("list skills", () => native!.rpc.skills.list()).pipe(
            Effect.result,
          );
          if (skills._tag === "Success")
            options.onSkills?.(cwd, skillsFromSdk(skills.success.skills as SkillsLoadedSkill[]));
          yield* drain();
          return createdThread;
        });
      const startTurn: ProviderAdapter.ProviderAdapterV2SessionRuntime["startTurn"] = Effect.fn(
        "CopilotAdapter.startTurn",
      )(function* (turnInput) {
        if (
          !native ||
          !providerThread ||
          stopped ||
          alreadyInUse ||
          turnInput.modelSelection.instanceId !== input.instanceId
        )
          return yield* new ProviderAdapter.ProviderAdapterTurnStartError({
            driver: COPILOT_DRIVER,
            providerThreadId: turnInput.providerThread.id,
            threadId: turnInput.threadId,
            runId: turnInput.runId,
          });
        if (active && !active.finished)
          return yield* new ProviderAdapter.ProviderAdapterProtocolError({
            driver: COPILOT_DRIVER,
            detail: "Previous Copilot turn is still active",
            reason: "previous_turn_active",
          });
        const effort = reasoningEffort(turnInput.modelSelection);
        const autoTier =
          turnInput.modelSelection.model === "auto"
            ? yield* sdk("validate routing selection", async () =>
                autoTierForSelection(
                  turnInput.modelSelection,
                  (await native!.rpc.model.list()).auto,
                ),
              )
            : yield* sdk("validate model selection", async () =>
                autoTierForSelection(turnInput.modelSelection),
              );
        yield* sdk("set model", () =>
          native!.setModel(turnInput.modelSelection.model, {
            ...(effort ? { reasoningEffort: effort } : {}),
            ...(autoTier ? { autoTier } : {}),
          }),
        );
        const modeResult = yield* sdk("set mode", () =>
          native!.rpc.mode.set({
            mode: turnInput.runtimePolicy.interactionMode === "plan" ? "plan" : "interactive",
          }),
        );
        if (modeResult.modeApplied === false || modeResult.deferImplementation === true) {
          return yield* new ProviderAdapter.ProviderAdapterProtocolError({
            driver: COPILOT_DRIVER,
            detail: "Copilot did not apply the requested interaction mode.",
          });
        }
        yield* drain();
        const now = yield* DateTime.now;
        const providerTurn: OrchestrationV2ProviderTurn = {
          id: ProviderTurnId.make(
            `${providerThread.id}:${turnInput.attemptId}:${turnInput.providerTurnOrdinal}`,
          ),
          providerThreadId: providerThread.id,
          nodeId: turnInput.rootNodeId,
          runAttemptId: turnInput.attemptId,
          nativeTurnRef: null,
          ordinal: turnInput.providerTurnOrdinal,
          status: "running",
          startedAt: now,
          completedAt: null,
        };
        const turn: ActiveTurn = {
          input: turnInput,
          providerTurn,
          nextOrdinal: 1,
          items: new Map(),
          accepted: false,
          idle: false,
          interrupted: false,
          finished: false,
        };
        active = turn;
        lastTurn = turn;
        turns.set(providerTurn.id, providerTurn);
        yield* emit({
          type: "provider_turn.updated",
          driver: COPILOT_DRIVER,
          threadId: open.threadId,
          providerTurn,
        });
        yield* updateThread({
          status: "active",
          firstRunOrdinal: providerThread.firstRunOrdinal ?? turnInput.runOrdinal,
          lastRunOrdinal: turnInput.runOrdinal,
          nativeMetadata: {
            ...providerThread.nativeMetadata,
            modelSelection: turnInput.modelSelection,
          },
        });
        if (turnInput.modelSelection.model === "auto")
          yield* refreshSelection(turnInput.modelSelection, turn);
        const userText = yield* providerMessageTextWithAttachmentPaths({
          text: turnInput.message.text,
          attachments: turnInput.message.attachments,
          resolveAttachmentPath: host.resolveAttachmentPath,
        });
        const instructions = buildRuntimeInstructions({
          harness: "GitHub Copilot",
          model: turnInput.modelSelection.model,
          reasoningEffort: effort,
        });
        const context = turnInput.appContext?.map((entry) => entry.text).join("\n\n") ?? "";
        const prompt = [instructions, history, context, userText].filter(Boolean).join("\n\n");
        const attachments: NonNullable<MessageOptions["attachments"]> = [];
        for (const attachment of turnInput.message.attachments) {
          const path = host.resolveAttachmentPath(attachment);
          if (!path)
            return yield* new ProviderAdapter.ProviderAdapterProtocolError({
              driver: COPILOT_DRIVER,
              detail: "Copilot attachment is unavailable",
              reason: "attachment_unreadable",
            });
          attachments.push({ type: "file" as const, path, displayName: attachment.name });
        }
        history = "";
        yield* sdk(
          "send",
          () =>
            native!.send({
              prompt,
              mode: "immediate",
              agentMode:
                turnInput.runtimePolicy.interactionMode === "plan" ? "plan" : "interactive",
              ...(attachments.length ? { attachments } : {}),
            }),
          30_000,
        ).pipe(
          Effect.tapError(() =>
            Effect.sync(() => {
              active = undefined;
            }),
          ),
        );
        turn.accepted = true;
        yield* Queue.offer(inbox, { type: "accepted" });
      });
      return {
        instanceId: input.instanceId,
        driver: COPILOT_DRIVER,
        providerSessionId: open.providerSessionId,
        providerSession,
        events: Stream.fromQueue(events),
        hasPendingBackgroundWork: Effect.sync(() => [...tasks.values()].some(isPendingTask)),
        ensureThread,
        resumeThread: (resume) =>
          ensureThread({
            threadId: resume.threadId ?? open.threadId,
            existingProviderThread: resume.providerThread,
            modelSelection: resume.modelSelection ?? open.modelSelection,
            runtimePolicy: resume.runtimePolicy ?? open.runtimePolicy,
          }),
        injectHistory: (context) =>
          Effect.sync(() => {
            history = context.context;
            return true;
          }),
        startTurn,
        steerTurn: (steer) =>
          Effect.fail(
            new ProviderAdapter.ProviderAdapterSteerRunUnsupportedError({
              driver: COPILOT_DRIVER,
              providerThreadId: steer.providerThread.id,
            }),
          ),
        interruptTurn: Effect.fn("CopilotAdapter.interruptTurn")(function* () {
          if (!native || !active) return;
          active.interrupted = true;
          yield* sdk("abort", () => native!.abort());
        }),
        stopTask: ({ taskId }) =>
          sdk("cancel task", () => native!.rpc.tasks.cancel({ id: taskId })).pipe(Effect.asVoid),
        respondToRuntimeRequest: Effect.fn("CopilotAdapter.respondToRuntimeRequest")(
          function* (response) {
            const entry = pending.get(response.requestId);
            const permissionReplyKey = `${response.decision ?? ""}\n${response.feedback ?? ""}`;
            if (
              !entry &&
              confirmedPermissionReplies.get(response.requestId) === permissionReplyKey &&
              response.answers === undefined
            )
              return;
            if (!entry)
              return yield* new ProviderAdapter.ProviderAdapterRuntimeRequestResponseError({
                driver: COPILOT_DRIVER,
                requestId: response.requestId,
              });
            const answer = response.answers?.answer;
            const validAnswer =
              typeof answer === "string" ||
              (Array.isArray(answer) && answer.every((part) => typeof part === "string"));
            if (
              entry.request.kind === "user_input"
                ? !validAnswer
                : !["accept", "decline", "cancel"].includes(response.decision ?? "") ||
                  response.answers !== undefined
            ) {
              return yield* new ProviderAdapter.ProviderAdapterRuntimeRequestResponseError({
                driver: COPILOT_DRIVER,
                requestId: response.requestId,
                cause: new Error(
                  "Copilot requires a supported one-time decision or a text answer.",
                ),
              });
            }
            if (entry.responseOwnedByV2) {
              if (!entry.nativePermissionId || entry.permissionReplyKey !== permissionReplyKey) {
                return yield* new ProviderAdapter.ProviderAdapterRuntimeRequestResponseError({
                  driver: COPILOT_DRIVER,
                  requestId: response.requestId,
                });
              }
              if (entry.permissionReplyReceipt)
                return yield* Deferred.await(entry.permissionReplyReceipt);
            }
            // V2 already recorded the answer. Ownership must survive even a failed native receipt.
            entry.responseOwnedByV2 = true;
            const receipt = Deferred.makeUnsafe<void, ProviderAdapter.ProviderAdapterV2Error>();
            if (entry.nativePermissionId) {
              entry.permissionReplyKey = permissionReplyKey;
              entry.permissionReplyReceipt = receipt;
            }
            return yield* Effect.gen(function* () {
              const now = yield* DateTime.now;
              if (entry.nativePermissionId) {
                yield* decidePermission(
                  entry.nativePermissionId,
                  response.decision === "accept"
                    ? { kind: "approve-once" }
                    : {
                        kind: "reject",
                        ...(response.feedback ? { feedback: response.feedback } : {}),
                      },
                );
                confirmedPermissionReplies.set(response.requestId, permissionReplyKey);
              }
              pending.delete(response.requestId);
              entry.owner.items.set(response.requestId, {
                ...entry.item,
                status: "completed",
                completedAt: now,
                updatedAt: now,
              });
              // The decider owns resolution and delivery state; callback handoff is the last operation.
              if (!entry.nativePermissionId) entry.resolve(response);
            }).pipe(
              Effect.onExit((exit) => {
                delete entry.permissionReplyReceipt;
                return Deferred.done(receipt, exit);
              }),
            );
          },
        ),
        readThreadSnapshot: Effect.fn("CopilotAdapter.readThreadSnapshot")(function* () {
          yield* drain();
          if (!providerThread)
            return yield* new ProviderAdapter.ProviderAdapterProtocolError({
              driver: COPILOT_DRIVER,
              detail: "Copilot thread is not loaded",
            });
          return {
            providerThread,
            providerTurns: [...turns.values()],
            messages: [...messages.values()],
            runtimeRequests: [...pending.values()]
              .filter((entry) => !entry.responseOwnedByV2)
              .map((entry) => entry.request),
          };
        }),
        rollbackThread: (rollback) =>
          Effect.fail(
            new ProviderAdapter.ProviderAdapterRollbackThreadError({
              driver: COPILOT_DRIVER,
              providerThreadId: rollback.providerThread.id,
              cause: new Error("Native Copilot rollback is unsupported."),
            }),
          ),
        forkThread: (fork) =>
          Effect.fail(
            new ProviderAdapter.ProviderAdapterForkThreadError({
              driver: COPILOT_DRIVER,
              providerThreadId: fork.sourceProviderThread.id,
              cause: new Error("Native Copilot fork is unsupported."),
            }),
          ),
      } satisfies ProviderAdapter.ProviderAdapterV2SessionRuntime;
    }),
  });
});

import { assert, describe, it } from "@effect/vitest";
import type { SessionEvent } from "@github/copilot-sdk";
import { normalizeFusionExecution, fusionExecutionKey, ROOT_PHASE_GAP } from "./fusion.ts";

const start = "2026-10-30T00:00:00.000Z";
const end = "2026-10-30T00:00:02.000Z";
const receipt = "2026-10-30T00:00:04.000Z";
function event(type: SessionEvent["type"], data: object, timestamp = end, id = type): SessionEvent {
  return { type, data, timestamp, id, parentId: "chronological-not-semantic" } as SessionEvent;
}
const phase = { fusionId: "fusion-a", phaseId: "primary-1", model: "same-model", role: "primary" };

describe("bounded Copilot execution metadata", () => {
  it("keeps overlapping repeated models separate, ignores activity, and never copies drafts or usage", () => {
    const first = event("assistant.fusion_phase_completed", {
      ...phase,
      durationMs: 2000,
      status: "completed",
      content: "PRIVATE DRAFT",
      usage: { inputTokens: 100 },
      verdict: "PRIVATE CRITIC",
    });
    const second = event("assistant.fusion_phase_completed", {
      ...phase,
      phaseId: "critic-2",
      role: "critic",
      durationMs: 2000,
      status: "completed",
    });
    assert.notEqual(fusionExecutionKey(first), fusionExecutionKey(second));
    const metadata = normalizeFusionExecution(first, "session", receipt)!;
    assert.equal(metadata.startedAt, start);
    assert.equal(metadata.startSource, "estimated");
    assert.equal(metadata.durationMs, 2000);
    assert.equal(metadata.sourceTimestamp, end);
    assert.equal(metadata.receivedAt, receipt);
    assert.notInclude(JSON.stringify(metadata), "PRIVATE");
    assert.notInclude(JSON.stringify(metadata), "inputTokens");
    assert.isUndefined(
      normalizeFusionExecution(event("assistant.fusion_phase_activity", phase), "session", receipt),
    );
  });

  it("retains terminal status when a delayed start arrives and upgrades estimated timing", () => {
    const done = normalizeFusionExecution(
      event("assistant.fusion_phase_completed", {
        ...phase,
        durationMs: 2000,
        status: "completed",
      }),
      "session",
      receipt,
    )!;
    const delayed = normalizeFusionExecution(
      event(
        "assistant.fusion_phase_started",
        {
          ...phase,
          pattern: "cascade",
        },
        start,
      ),
      "session",
      receipt,
      done,
    )!;
    assert.equal(delayed.status, "completed");
    assert.equal(delayed.startSource, "observed");
    assert.equal(delayed.endedAt, end);
    assert.deepEqual(delayed.gaps, []);
    const replay = normalizeFusionExecution(
      event("assistant.fusion_phase_completed", {
        ...phase,
        durationMs: 2000,
        status: "completed",
      }),
      "session",
      receipt,
      delayed,
    )!;
    assert.equal(replay.startSource, "observed");
    assert.equal(replay.startedAt, start);
  });

  it("records failures without provider error text and preserves unknown durations", () => {
    const failed = normalizeFusionExecution(
      event("assistant.fusion_phase_failed", {
        ...phase,
        durationMs: Number.NaN,
        status: "failed",
        reason: "provider-unavailable",
        errorMessage: "PRIVATE PROVIDER RESPONSE",
      }),
      "session",
      receipt,
    )!;
    assert.equal(failed.reason, "provider-unavailable");
    assert.equal(failed.startSource, "unknown");
    assert.isUndefined(failed.durationMs);
    assert.notInclude(JSON.stringify(failed), "PRIVATE");
  });

  it("does not resurrect a phase from a late start after the root ended without terminal telemetry", () => {
    const execution = normalizeFusionExecution(
      event("assistant.fusion_phase_started", phase, start),
      "session",
      receipt,
    )!;
    const missing = { ...execution, status: "unknown", gaps: [ROOT_PHASE_GAP] };
    const late = normalizeFusionExecution(
      event("assistant.fusion_phase_started", phase, end),
      "session",
      receipt,
      missing,
    )!;
    assert.equal(late.status, "unknown");
    assert.equal(late.startedAt, start);
    assert.isUndefined(late.endedAt);
    assert.deepEqual(late.gaps, [ROOT_PHASE_GAP]);
  });

  it("separates planned models from execution and retains aggregate final source without token duplication", () => {
    const resolved = event("session.fusion_resolved", {
      fusionId: "fusion-a",
      turnId: "0",
      pattern: "critique",
      contractVersion: 999,
      primaryModel: "draft",
      secondaryModel: "review",
      fallbackModel: "fallback",
      syntheticModel: "auto",
      critics: [{ model: "critic", phaseId: "c1" }],
    });
    const plan = normalizeFusionExecution(resolved, "session", receipt)!;
    assert.equal(plan.status, "planned");
    assert.isUndefined(plan.model);
    assert.equal(plan.plannedModels?.length, 3);
    assert.include(plan.gaps[0], "Unrecognized");
    const done = normalizeFusionExecution(
      event("session.fusion_completed", {
        fusionId: "fusion-a",
        turnId: "0",
        pattern: "critique",
        outcome: "completed",
        durationMs: 2000,
        syntheticModel: "auto",
        finalSourceModel: "draft",
        finalSourcePhaseId: "primary-1",
        awaitingBackgroundWork: true,
        inputTokens: 1000,
        totalNanoAiu: 1000,
      }),
      "session",
      receipt,
      plan,
    )!;
    assert.equal(done.finalSourceModel, "draft");
    assert.isTrue(done.awaitingBackgroundWork);
    assert.notInclude(JSON.stringify(done), "inputTokens");
    assert.notInclude(JSON.stringify(done), "totalNanoAiu");
    assert.equal(normalizeFusionExecution(resolved, "session", receipt, done)?.status, "completed");
  });

  it("does not derive identity or run ownership from chronological parent links", () => {
    const failed = event("session.fusion_route_failed", {
      attemptId: "attempt",
      fallbackModel: "explicit",
      policy: "opaque",
      reason: "route-failed",
      syntheticModel: "auto",
      errorMessage: "PRIVATE",
    });
    const metadata = normalizeFusionExecution(failed, "session", receipt)!;
    assert.isUndefined(metadata.nativeTurnId);
    assert.isUndefined(metadata.fusionId);
    assert.equal(metadata.fallbackModel, "explicit");
    assert.notInclude(JSON.stringify(metadata), "chronological");
    assert.throws(
      () =>
        fusionExecutionKey(
          event("assistant.fusion_phase_started", {
            ...phase,
            phaseId: "x".repeat(513),
          }),
        ),
      /metadata bound/,
    );
  });
});

import type { SessionEvent } from "@github/copilot-sdk";
import type { OrchestrationV2ModelExecution } from "@t3tools/contracts";
import * as DateTime from "effect/DateTime";

export const MAX_EXECUTION_ITEMS = 128;
export const MAX_REPLAY_EXECUTION_EVENTS = 512;
export const ROOT_PHASE_GAP = "The root turn ended without terminal phase telemetry.";

const label = (value: string) => value.slice(0, 512);
const duration = (value: number) =>
  Number.isFinite(value) ? Math.max(0, Math.trunc(value)) : undefined;

export function fusionExecutionKey(event: SessionEvent): string | undefined {
  const identity = "fusionId" in event.data ? event.data.fusionId : undefined;
  const phase = "phaseId" in event.data ? event.data.phaseId : undefined;
  if (
    (typeof identity === "string" && identity.length > 512) ||
    (typeof phase === "string" && phase.length > 512)
  )
    throw new Error("Copilot execution identity exceeds the supported metadata bound.");
  switch (event.type) {
    case "session.fusion_resolved":
    case "session.fusion_completed":
      return `fusion:${event.data.fusionId}:route`;
    case "session.fusion_route_failed":
      return `fusion:${event.data.fusionId ?? event.data.attemptId}:route`;
    case "assistant.fusion_phase_started":
    case "assistant.fusion_phase_completed":
    case "assistant.fusion_phase_failed":
      return `fusion:${event.data.fusionId}:phase:${event.data.phaseId}`;
    default:
      return undefined;
  }
}

export function normalizeFusionExecution(
  event: SessionEvent,
  nativeSessionId: string,
  receivedAt: string,
  previous?: OrchestrationV2ModelExecution,
): OrchestrationV2ModelExecution | undefined {
  if (!fusionExecutionKey(event)) return undefined;
  const base: OrchestrationV2ModelExecution = {
    version: 1,
    kind: "route",
    nativeSessionId,
    eventId: event.id,
    sourceTimestamp: event.timestamp,
    receivedAt,
    status: "planned",
    startSource: "unknown",
    gaps: [],
  };
  switch (event.type) {
    case "session.fusion_resolved": {
      const data = event.data;
      const plannedModels = [
        { model: label(data.primaryModel), role: "primary" },
        ...(data.secondaryModel ? [{ model: label(data.secondaryModel), role: "secondary" }] : []),
        ...(data.judgeModel ? [{ model: label(data.judgeModel), role: "judge" }] : []),
        ...(data.repairModel ? [{ model: label(data.repairModel), role: "repair" }] : []),
        ...(data.critics ?? []).slice(0, 60).map((critic) => ({
          model: label(critic.model),
          role: "critic",
          phaseId: critic.phaseId,
        })),
      ];
      // Replaying the route must not erase a later authoritative completion.
      if (previous?.endedAt) return { ...previous, plannedModels };
      return {
        ...base,
        fusionId: data.fusionId,
        nativeTurnId: data.turnId,
        syntheticModel: label(data.syntheticModel),
        pattern: data.pattern,
        fallbackModel: label(data.fallbackModel),
        contractVersion: data.contractVersion,
        plannedModels,
        gaps: [
          ...(data.contractVersion !== 1
            ? ["Unrecognized routing contract version; execution facts may be incomplete."]
            : []),
          ...((data.critics?.length ?? 0) > 60
            ? ["The routing plan was truncated to 64 models."]
            : []),
        ],
      };
    }
    case "session.fusion_completed":
      return {
        ...(previous ?? base),
        kind: "route",
        fusionId: event.data.fusionId,
        nativeTurnId: event.data.turnId,
        eventId: event.id,
        sourceTimestamp: event.timestamp,
        receivedAt,
        status: event.data.outcome,
        pattern: event.data.pattern,
        syntheticModel: label(event.data.syntheticModel),
        endedAt: event.timestamp,
        durationMs: duration(event.data.durationMs),
        ...(event.data.finalSourceModel
          ? { finalSourceModel: label(event.data.finalSourceModel) }
          : {}),
        ...(event.data.finalSourcePhaseId
          ? { finalSourcePhaseId: event.data.finalSourcePhaseId }
          : {}),
        ...(event.data.degradedReason ? { reason: label(event.data.degradedReason) } : {}),
        awaitingBackgroundWork: event.data.awaitingBackgroundWork ?? false,
        gaps: previous?.gaps ?? ["The resolved routing plan was not observed."],
      };
    case "session.fusion_route_failed":
      return {
        ...(previous ?? base),
        kind: "route",
        ...(event.data.fusionId ? { fusionId: event.data.fusionId } : {}),
        eventId: event.id,
        sourceTimestamp: event.timestamp,
        receivedAt,
        status: "routing-failed",
        reason: label(event.data.reason),
        syntheticModel: label(event.data.syntheticModel),
        fallbackModel: label(event.data.fallbackModel),
        gaps: previous?.gaps ?? [
          "Native turn association is unavailable for this routing failure.",
        ],
      };
    case "assistant.fusion_phase_started": {
      if (previous?.status === "unknown" && previous.gaps.includes(ROOT_PHASE_GAP))
        return {
          ...previous,
          receivedAt,
          startedAt: previous.startSource === "observed" ? previous.startedAt : event.timestamp,
          startSource: "observed",
        };
      if (previous?.endedAt) {
        if (Date.parse(event.timestamp) > Date.parse(previous.endedAt)) return previous;
        return {
          ...previous,
          startedAt: event.timestamp,
          startSource: "observed",
          gaps: previous.gaps.filter(
            (gap) => gap !== "Phase start was not observed; its start time is only an estimate.",
          ),
        };
      }
      return {
        ...base,
        kind: "phase",
        fusionId: event.data.fusionId,
        phaseId: event.data.phaseId,
        phaseKind: event.data.phaseKind,
        conversationScope: event.data.conversationScope,
        model: label(event.data.model),
        role: label(event.data.role),
        pattern: event.data.pattern,
        status: "running",
        startedAt: event.timestamp,
        startSource: "observed",
      };
    }
    case "assistant.fusion_phase_completed":
    case "assistant.fusion_phase_failed": {
      const elapsed = duration(event.data.durationMs);
      const observed = previous?.startSource === "observed";
      const end = Date.parse(event.timestamp);
      return {
        ...(previous ?? base),
        kind: "phase",
        fusionId: event.data.fusionId,
        phaseId: event.data.phaseId,
        phaseKind: event.data.phaseKind,
        conversationScope: event.data.conversationScope,
        model: label(event.data.model),
        role: label(event.data.role),
        status: event.data.status,
        eventId: event.id,
        sourceTimestamp: event.timestamp,
        receivedAt,
        endedAt: event.timestamp,
        durationMs: elapsed,
        ...(event.type === "assistant.fusion_phase_completed" &&
        event.data.endedWithBackgroundWork !== undefined
          ? { endedWithBackgroundWork: event.data.endedWithBackgroundWork }
          : {}),
        ...(observed
          ? { startedAt: previous.startedAt, startSource: "observed" as const }
          : elapsed !== undefined && Number.isFinite(end) && end >= elapsed
            ? {
                startedAt: DateTime.formatIso(DateTime.makeUnsafe(end - elapsed)),
                startSource: "estimated" as const,
              }
            : { startSource: "unknown" as const }),
        ...(event.type === "assistant.fusion_phase_failed"
          ? {
              reason: label(event.data.reason),
              ...(event.data.degradedToPhaseId
                ? { degradedToPhaseId: event.data.degradedToPhaseId }
                : {}),
            }
          : {}),
        gaps: observed
          ? []
          : [
              elapsed !== undefined
                ? "Phase start was not observed; its start time is only an estimate."
                : "Phase start and usable elapsed time were not observed.",
            ],
      };
    }
    default:
      return undefined;
  }
}

import { assert, describe, it } from "@effect/vitest";
import { ProviderInstanceId } from "@t3tools/contracts";
import { autoTierForSelection, routingDescriptor, type AutoCatalog } from "./routing.ts";

const instanceId = ProviderInstanceId.make("account-a");
export const autoCatalog: AutoCatalog = {
  defaultTier: "standard",
  tiers: [
    {
      id: "standard",
      displayName: "Standard",
      description: "",
      type: "auto",
      status: { enabled: true },
    },
    {
      id: "fuse@2026:opaque",
      displayName: "Fusion",
      description: "Account routing",
      type: "fusion",
      fusionTier: "do-not-translate",
      status: { enabled: true },
    },
    {
      id: "blocked",
      displayName: "Unavailable",
      description: "",
      type: "fusion",
      status: { enabled: false, message: "Your account policy disables this." },
    },
    {
      id: "hidden",
      displayName: "Hidden",
      description: "",
      type: "fusion",
      status: { enabled: true, pickerVisible: false },
    },
  ],
};

describe("account-advertised routing", () => {
  it("uses opaque IDs without aliases, honors visibility, and exposes disabled reasons", () => {
    const descriptor = routingDescriptor(autoCatalog);
    assert.deepEqual(
      descriptor.options.map((option) => option.id),
      ["standard", "fuse@2026:opaque", "blocked"],
    );
    assert.equal(descriptor.options[2]?.disabledReason, "Your account policy disables this.");
    assert.equal(descriptor.currentValue, "standard");
    const selection = {
      instanceId,
      model: "auto",
      options: [{ id: "autoTier", value: "fuse@2026:opaque" }],
    };
    assert.equal(autoTierForSelection(selection, autoCatalog), "fuse@2026:opaque");
    assert.isUndefined(autoTierForSelection({ instanceId, model: "auto" }, autoCatalog));
    assert.isUndefined(autoTierForSelection({ instanceId, model: "explicit" }));
  });

  it("refuses unknown, hidden, policy-disabled and unsupported destination choices", () => {
    for (const id of ["blocked", "hidden", "unknown"])
      assert.throws(() =>
        autoTierForSelection(
          {
            instanceId,
            model: "auto",
            options: [{ id: "autoTier", value: id }],
          },
          autoCatalog,
        ),
      );
    assert.throws(() => autoTierForSelection({ instanceId, model: "auto" }), /does not advertise/);
    assert.throws(
      () =>
        autoTierForSelection(
          {
            instanceId,
            model: "explicit",
            options: [{ id: "autoTier", value: "standard" }],
          },
          autoCatalog,
        ),
      /requires/,
    );
  });
});

import type { CopilotClient } from "@github/copilot-sdk";
import type { ModelSelection, SelectProviderOptionDescriptor } from "@t3tools/contracts";
import { getModelSelectionStringOptionValue } from "@t3tools/shared/model";

export type ModelCatalog = Awaited<ReturnType<CopilotClient["rpc"]["models"]["list"]>>;
export type AutoCatalog = NonNullable<ModelCatalog["auto"]>;

export function routingDescriptor(auto: AutoCatalog): SelectProviderOptionDescriptor {
  const seen = new Set<string>();
  const options = auto.tiers.flatMap((tier) => {
    if (
      !tier.id ||
      tier.id.length > 512 ||
      tier.id !== tier.id.trim() ||
      seen.has(tier.id) ||
      tier.status.pickerVisible === false
    )
      return [];
    seen.add(tier.id);
    return [
      {
        id: tier.id,
        label: tier.displayName.trim() || tier.id,
        ...(tier.description.trim() ? { description: tier.description.trim() } : {}),
        ...(!tier.status.enabled
          ? {
              disabledReason:
                tier.status.message?.trim() ||
                tier.status.reason?.trim() ||
                "Unavailable for this account.",
            }
          : {}),
        ...(tier.id === auto.defaultTier && tier.status.enabled ? { isDefault: true } : {}),
      },
    ];
  });
  return {
    id: "autoTier",
    label: "Routing",
    type: "select",
    options,
    ...(options.some((option) => option.id === auto.defaultTier && !option.disabledReason)
      ? { currentValue: auto.defaultTier }
      : {}),
  };
}

export function autoTierForSelection(selection: ModelSelection, auto?: AutoCatalog) {
  const requested = getModelSelectionStringOptionValue(selection, "autoTier");
  if (selection.model !== "auto") {
    if (requested)
      throw new Error("A Copilot routing preference requires the account-advertised auto model.");
    return undefined;
  }
  if (!auto)
    throw new Error("This Copilot runtime/account does not advertise Auto or Fusion routing.");
  const id = requested ?? auto.defaultTier;
  const tier = auto.tiers.find((entry) => entry.id === id);
  if (!tier || tier.id.length > 512 || !tier.status.enabled || tier.status.pickerVisible === false)
    throw new Error(
      tier?.status.message ||
        tier?.status.reason ||
        "The requested Copilot routing preference is unavailable for this account.",
    );
  return requested;
}

import { assert, describe, it } from "@effect/vitest";
import type { ModelInfo, SkillsLoadedSkill } from "@github/copilot-sdk";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";
import { CopilotSettings } from "../settings.ts";
import { checkStatus, modelsFromSdk, skillsFromSdk } from "./status.ts";
import { bundledCliPath, resolveClientConfiguration } from "./client.ts";
import type { AutoCatalog } from "./routing.ts";

const decode = Schema.decodeSync(CopilotSettings);
const model = (id: string, extra: Partial<ModelInfo> = {}): ModelInfo => ({
  id,
  name: id,
  capabilities: {
    supports: { vision: true, reasoningEffort: true },
    limits: { max_context_window_tokens: 128_000 },
  },
  ...extra,
});
const skill = (
  name: string,
  source: SkillsLoadedSkill["source"],
  extra: Partial<SkillsLoadedSkill> = {},
): SkillsLoadedSkill => ({
  name,
  source,
  description: `${name} skill`,
  enabled: true,
  userInvocable: true,
  path: `/workspace/${name}/SKILL.md`,
  ...extra,
});

describe("Copilot discovery and account isolation", () => {
  it("adds advertised Auto routing without replacing explicit-model defaults", () => {
    const auto: AutoCatalog = {
      defaultTier: "opaque-tier",
      tiers: [
        {
          id: "opaque-tier",
          displayName: "Fusion",
          description: "Account supplied",
          type: "fusion",
          status: { enabled: true },
        },
      ],
    };
    const result = modelsFromSdk([model("explicit")], decode({}), auto);
    assert.deepEqual(
      result.map((entry) => entry.slug),
      ["explicit", "auto"],
    );
    assert.isTrue(result[0]?.isDefault);
    assert.isUndefined(result[1]?.isDefault);
    assert.equal(result[1]?.capabilities?.optionDescriptors?.[0]?.id, "autoTier");
    assert.deepEqual(
      modelsFromSdk([model("explicit")], decode({})).map((entry) => entry.slug),
      ["explicit"],
    );
  });
  it("keeps project/native skills in workspace results, including pathless built-ins", () => {
    const skills = skillsFromSdk([
      skill("project-skill", "project"),
      skill("personal-skill", "personal-copilot"),
      skill("builtin", "builtin", { path: "" }),
      skill("disabled", "project", { enabled: false }),
      skill("agent-only", "project", { userInvocable: false }),
      skill("project-skill", "personal-agents"),
    ]);
    assert.deepEqual(
      skills.map((entry) => entry.name),
      ["project-skill", "personal-skill", "builtin"],
    );
    assert.equal(skills[0]?.scope, "project");
    assert.equal(skills[2]?.path, "copilot://skills/builtin");
  });

  it("discovers allowed models and reasoning options without duplicates or policy-disabled models", () => {
    const result = modelsFromSdk(
      [
        model("gpt", {
          supportedReasoningEfforts: ["low", "high"],
          defaultReasoningEffort: "high",
        }),
        model("gpt"),
        model("blocked", { policy: { state: "disabled", terms: "" } }),
      ],
      decode({ customModels: ["custom"] }),
    );
    assert.deepEqual(
      result.map((entry) => entry.slug),
      ["gpt", "custom"],
    );
    assert.deepEqual(result[0]?.capabilities?.optionDescriptors?.[0], {
      id: "reasoningEffort",
      label: "Reasoning",
      type: "select",
      currentValue: "high",
      options: [
        { id: "low", label: "Low" },
        { id: "high", label: "High", isDefault: true },
      ],
    });
  });

  it("uses only the selected account's home and preserves SDK-owned native paths", () => {
    const first = resolveClientConfiguration({
      settings: decode({ homePath: "~/.copilot-work" }),
      cwd: "/workspace",
      environment: { HOME: "/accounts/first", COPILOT_HOME: "/ignored", GITHUB_TOKEN: "first" },
    });
    const second = resolveClientConfiguration({
      settings: decode({}),
      cwd: "/workspace",
      environment: { HOME: "/accounts/second", COPILOT_HOME: "/native/second" },
    });
    assert.equal(first.effectiveHome, "/accounts/first/.copilot-work");
    assert.equal(first.options.mode, "copilot-cli");
    assert.equal(first.options.baseDirectory, first.effectiveHome);
    assert.equal(first.options.env?.COPILOT_HOME, first.effectiveHome);
    assert.equal(second.effectiveHome, "/native/second");
    assert.isUndefined(second.options.env?.GITHUB_TOKEN);
  });

  it("resolves packaged Windows executables outside asar and Linux libc alternatives", () => {
    assert.equal(
      bundledCliPath({
        packaged: true,
        electron: true,
        platform: "win32",
        architecture: "x64",
        resolve: () =>
          "C:\\T3\\app.asar\\node_modules\\@github\\copilot-sdk-win32-x64\\package.json",
        exists: (path) => path.includes("app.asar.unpacked"),
      }),
      "C:\\T3\\app.asar.unpacked\\node_modules\\@github\\copilot-sdk-win32-x64\\prebuilds\\win32-x64\\copilot-runtime.exe",
    );
    assert.equal(
      bundledCliPath({
        packaged: true,
        electron: false,
        platform: "linux",
        architecture: "arm64",
        resolve: (name) => {
          if (!name.includes("linuxmusl")) throw new Error("not installed");
          return "/native/package.json";
        },
        exists: () => true,
      }),
      "/native/prebuilds/linuxmusl-arm64/copilot-runtime",
    );
    assert.throws(() =>
      bundledCliPath({
        packaged: true,
        electron: false,
        platform: "darwin",
        architecture: "arm64",
        resolve: () => "/native/package.json",
        exists: (path) => !path.endsWith("runtime.node"),
      }),
    );
  });

  it.effect("returns authenticated SDK models without exposing any workspace skills globally", () =>
    Effect.gen(function* () {
      let stops = 0;
      const result = yield* checkStatus(
        decode({ enabled: true }),
        "/workspace",
        { HOME: "/account" },
        () => ({
          start: async () => {},
          stop: async () => {
            stops++;
            return [];
          },
          forceStop: async () => {},
          getStatus: async () => ({ version: "1.0.75", protocolVersion: 1 }),
          getAuthStatus: async () => ({ isAuthenticated: true, login: "octocat" }),
          rpc: { models: { list: async () => ({ models: [model("gpt")] }) } },
        }),
      );
      assert.equal(result.status, "ready");
      assert.equal(result.auth.label, "octocat");
      assert.equal(result.models[0]?.slug, "gpt");
      assert.deepEqual(result.skills, []);
      assert.equal(stops, 1);
    }),
  );

  it.effect(
    "reports cleanup-only failures and preserves a primary probe failure when cleanup also fails",
    () =>
      Effect.gen(function* () {
        for (const failProbe of [false, true]) {
          let forced = 0;
          const snapshot = yield* checkStatus(decode({ enabled: true }), "/workspace", {}, () => ({
            start: async () => {},
            stop: async () => {
              throw new Error("stop failed");
            },
            forceStop: async () => {
              forced++;
            },
            getStatus: async () => {
              if (failProbe) throw new Error("probe failed");
              return { version: "1.0.75", protocolVersion: 1 };
            },
            getAuthStatus: async () => ({ isAuthenticated: true }),
            rpc: { models: { list: async () => ({ models: [] }) } },
          }));
          assert.equal(snapshot.status, "error");
          assert.equal(forced, 1);
          assert.equal(
            snapshot.message,
            failProbe ? "GitHub Copilot status check failed." : "GitHub Copilot cleanup failed.",
          );
        }
      }),
  );
});

import type { CopilotClient, SkillsLoadedSkill } from "@github/copilot-sdk";
import type { ServerProviderSkill } from "@t3tools/contracts";
import { createModelCapabilities } from "@t3tools/shared/model";
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import {
  buildSelectOptionDescriptor,
  buildServerProvider,
  providerModelsFromSettings,
} from "@t3tools/provider-core/server/snapshotProbe";
import type { CopilotSettings } from "../settings.ts";
import { createClient, resolveClientConfiguration } from "./client.ts";
import { routingDescriptor, type AutoCatalog, type ModelCatalog } from "./routing.ts";

const presentation = {
  displayName: "GitHub Copilot",
  badgeLabel: "Preview",
  showInteractionModeToggle: true,
  supportsConversationRollback: false,
};
const emptyCapabilities = createModelCapabilities({ optionDescriptors: [] });

export function modelsFromSdk(
  models: ReadonlyArray<ModelCatalog["models"][number]>,
  settings: CopilotSettings,
  auto?: AutoCatalog,
) {
  const seen = new Set<string>();
  return providerModelsFromSettings(
    models
      .flatMap((model) => {
        const slug = model.id.trim();
        if (
          !slug ||
          !model.name.trim() ||
          seen.has(slug) ||
          model.policy?.state === "disabled" ||
          (slug === "auto" && !auto)
        )
          return [];
        seen.add(slug);
        const efforts = model.supportedReasoningEfforts ?? [];
        const routing = slug === "auto" && auto ? routingDescriptor(auto) : undefined;
        return [
          {
            slug,
            name: model.name,
            isCustom: false,
            ...(seen.size === 1 ? { isDefault: true } : {}),
            capabilities: createModelCapabilities({
              optionDescriptors: [
                ...(routing ? [routing] : []),
                ...(efforts.length
                  ? [
                      buildSelectOptionDescriptor({
                        id: "reasoningEffort",
                        label: "Reasoning",
                        options: efforts.map((effort) => ({
                          value: effort,
                          label:
                            effort === "xhigh"
                              ? "Extra High"
                              : effort[0]!.toUpperCase() + effort.slice(1),
                          isDefault: effort === model.defaultReasoningEffort,
                        })),
                      }),
                    ]
                  : []),
              ],
            }),
          },
        ];
      })
      .concat(
        auto && !seen.has("auto") && !models.some((model) => model.id.trim() === "auto")
          ? [
              {
                slug: "auto",
                name: "Auto routing",
                isCustom: false,
                capabilities: createModelCapabilities({
                  optionDescriptors: [routingDescriptor(auto)],
                }),
              },
            ]
          : [],
      ),
    settings.customModels,
    emptyCapabilities,
  );
}

// Workspace snapshots are requested with a cwd; no project skills enter the instance snapshot.
export function skillsFromSdk(
  skills: ReadonlyArray<SkillsLoadedSkill>,
): ReadonlyArray<ServerProviderSkill> {
  const seen = new Set<string>();
  return skills.flatMap((skill) => {
    const name = skill.name.trim();
    if (!name || !skill.enabled || !skill.userInvocable || seen.has(name)) return [];
    seen.add(name);
    return [
      {
        name,
        ...(skill.description.trim() ? { description: skill.description } : {}),
        path: skill.path?.trim() || `copilot://skills/${encodeURIComponent(name)}`,
        enabled: true,
        scope: skill.source,
        userInvocable: true,
      },
    ];
  });
}

export const pendingSnapshot = (settings: CopilotSettings) =>
  DateTime.now.pipe(
    Effect.map((now) =>
      buildServerProvider({
        presentation,
        enabled: settings.enabled,
        checkedAt: DateTime.formatIso(now),
        models: modelsFromSdk([], settings),
        probe: {
          installed: false,
          version: null,
          status: "warning",
          auth: { status: "unknown" },
          message: settings.enabled
            ? "Checking GitHub Copilot availability..."
            : "GitHub Copilot is disabled.",
        },
      }),
    ),
  );

export type StatusClient = Pick<
  CopilotClient,
  "start" | "stop" | "forceStop" | "getStatus" | "getAuthStatus"
> & { readonly rpc: { readonly models: Pick<CopilotClient["rpc"]["models"], "list"> } };

export const checkStatus = Effect.fn("Copilot.checkStatus")(function* (
  settings: CopilotSettings,
  cwd: string,
  environment: NodeJS.ProcessEnv,
  factory: (
    options: ReturnType<typeof resolveClientConfiguration>["options"],
  ) => StatusClient = createClient,
) {
  if (!settings.enabled) return yield* pendingSnapshot(settings);
  let started = false;
  let cleanupFailed = false;
  const probeError = (cause: unknown) => ({ _tag: "CopilotStatusProbeError" as const, cause });
  const checkedAt = DateTime.formatIso(yield* DateTime.now);
  const result = yield* Effect.scoped(
    Effect.gen(function* () {
      const client = yield* Effect.acquireRelease(
        Effect.try({
          try: () => factory(resolveClientConfiguration({ settings, cwd, environment }).options),
          catch: probeError,
        }),
        (client) =>
          Effect.gen(function* () {
            const stopped = yield* Effect.tryPromise({
              try: () => client.stop(),
              catch: probeError,
            }).pipe(Effect.timeoutOption(10_000), Effect.result);
            if (
              stopped._tag === "Failure" ||
              Option.isNone(stopped.success) ||
              stopped.success.value.length
            ) {
              cleanupFailed = true;
              yield* Effect.tryPromise({ try: () => client.forceStop(), catch: probeError }).pipe(
                Effect.timeoutOption(5_000),
                Effect.ignore,
              );
            }
          }),
      );
      return yield* Effect.tryPromise({
        try: async () => {
          await client.start();
          started = true;
          const [status, auth] = await Promise.all([client.getStatus(), client.getAuthStatus()]);
          const catalog = auth.isAuthenticated ? await client.rpc.models.list({}) : { models: [] };
          return { status, auth, catalog };
        },
        catch: probeError,
      });
    }),
  ).pipe(Effect.timeoutOption(30_000), Effect.result);
  if (result._tag === "Failure" || Option.isNone(result.success) || cleanupFailed) {
    return buildServerProvider({
      presentation,
      enabled: true,
      checkedAt,
      models: modelsFromSdk([], settings),
      probe: {
        installed: started,
        version: null,
        status: "error",
        auth: { status: "unknown" },
        message:
          cleanupFailed && result._tag === "Success" && Option.isSome(result.success)
            ? "GitHub Copilot cleanup failed."
            : started
              ? "GitHub Copilot status check failed."
              : "Unable to start the Copilot CLI.",
      },
    });
  }
  const { status, auth, catalog } = result.success.value;
  return buildServerProvider({
    presentation,
    enabled: true,
    checkedAt,
    models: modelsFromSdk(catalog.models, settings, catalog.auto),
    probe: {
      installed: true,
      version: status.version,
      status: auth.isAuthenticated ? "ready" : "error",
      auth: auth.isAuthenticated
        ? { status: "authenticated", ...(auth.login ? { label: auth.login } : {}) }
        : { status: "unauthenticated" },
      ...(!auth.isAuthenticated
        ? { message: "Sign in with `copilot login` in this provider's account environment." }
        : !catalog.auto
          ? {
              message:
                "This account/runtime does not advertise Auto or Fusion routing. Explicit models remain available.",
            }
          : {}),
    },
  });
});

